import { spawnSync } from "node:child_process";
import { execa } from "execa";
//#region src/plugins/run.ts
const TELEMETRY_BLOCKERS = ["DISABLE_TELEMETRY", "DO_NOT_TRACK"];
const PLUGIN_SOURCE = "neondatabase/agent-skills";
const NEON_PLUGIN_NAME = "neon-postgres";
const PLUGIN_SKILLS = [
	"neon",
	"neon-ai-gateway",
	"neon-auth",
	"neon-functions",
	"neon-object-storage",
	"neon-postgres",
	"neon-postgres-branches",
	"neon-postgres-egress-optimizer"
];
const PLUGINS_CLI_TIMEOUT_MS = 12e4;
const pluginsChildEnv = (base = process.env) => {
	const env = { ...base };
	for (const key of TELEMETRY_BLOCKERS) delete env[key];
	for (const key of Object.keys(env)) if (key.toUpperCase() === "NEON_API_KEY") delete env[key];
	return env;
};
const pluginsScopeFlag = (global) => global ? "user" : "project";
const pluginsAddArgs = (options) => {
	if (options.target.length === 0) throw new Error("plugins add needs a -t target.");
	return [
		"-y",
		"plugins",
		"add",
		PLUGIN_SOURCE,
		"-t",
		options.target,
		"-s",
		pluginsScopeFlag(options.global),
		"-y"
	];
};
const neonPluginsRetryCommand = (options) => {
	const args = ["plugins"];
	for (const agent of options.agents) args.push("--agent", agent);
	if (options.global) args.push("--global");
	args.push("-y");
	return `neon ${args.map(quoteNpxArg).join(" ")}`;
};
const quoteNpxArg = (part) => /[\s"'\\*]/.test(part) ? `'${part.replace(/'/g, `'\\''`)}'` : part;
const runPluginsCli = async (options) => {
	const timeoutMs = options.timeoutMs ?? 12e4;
	const subprocess = execa("npx", options.args, {
		cwd: options.cwd,
		env: pluginsChildEnv(options.env ?? process.env),
		extendEnv: false,
		stdio: "pipe",
		detached: true
	});
	let timedOut = false;
	let stopped = false;
	const stop = () => {
		if (stopped) return;
		stopped = true;
		if (subprocess.pid !== void 0) killProcessTree(subprocess.pid);
	};
	const onSigint = () => {
		stop();
		process.exit(130);
	};
	const onSigterm = () => {
		stop();
		process.exit(143);
	};
	process.once("SIGINT", onSigint);
	process.once("SIGTERM", onSigterm);
	process.once("exit", stop);
	const timer = setTimeout(() => {
		timedOut = true;
		stop();
	}, timeoutMs);
	try {
		const result = await subprocess;
		return {
			stdout: result.stdout,
			stderr: result.stderr
		};
	} catch (error) {
		if (isCommandMissing(error)) throw new Error("neon plugins needs npx (Node.js) to run the plugins CLI. Install Node.js, then retry.");
		if (isExecaFailure(error)) throw new Error(pluginsCliFailureMessage({
			stderr: typeof error.stderr === "string" ? error.stderr : "",
			stdout: typeof error.stdout === "string" ? error.stdout : "",
			timedOut,
			timeoutMs
		}));
		throw error;
	} finally {
		clearTimeout(timer);
		process.removeListener("SIGINT", onSigint);
		process.removeListener("SIGTERM", onSigterm);
		process.removeListener("exit", stop);
	}
};
const pluginsCliFailureMessage = (error) => {
	const childOut = [error.stderr, error.stdout].filter((part) => typeof part === "string" && part.length > 0).join("\n");
	if (error.timedOut === true) {
		const seconds = Math.max(1, Math.ceil((error.timeoutMs ?? 12e4) / 1e3));
		const headline = `plugins CLI timed out after ${seconds} ${seconds === 1 ? "second" : "seconds"}`;
		return childOut.length > 0 ? `${headline}:\n${childOut}` : `${headline}.`;
	}
	if (childOut.length > 0) return `plugins CLI failed:\n${childOut}`;
	return "plugins CLI failed.";
};
const killProcessTree = (pid) => {
	if (process.platform === "win32") {
		spawnSync("taskkill", [
			"/pid",
			String(pid),
			"/T",
			"/F"
		], { stdio: "ignore" });
		return;
	}
	try {
		process.kill(-pid, "SIGKILL");
	} catch {
		try {
			process.kill(pid, "SIGKILL");
		} catch {
			return;
		}
	}
};
const isCommandMissing = (error) => typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT";
const isExecaFailure = (error) => typeof error === "object" && error !== null && "shortMessage" in error && typeof error.shortMessage === "string";
//#endregion
export { NEON_PLUGIN_NAME, PLUGINS_CLI_TIMEOUT_MS, PLUGIN_SKILLS, PLUGIN_SOURCE, neonPluginsRetryCommand, pluginsAddArgs, pluginsChildEnv, pluginsCliFailureMessage, pluginsScopeFlag, quoteNpxArg, runPluginsCli };
